export const DOCS = [{"name": "nvgGlobalCompositeOperation","js": "globalCompositeOperation","section": "Composite operation","signature": "void nvgGlobalCompositeOperation(NVGcontext* ctx, int op)","doc": "The composite operations in NanoVG are modeled after HTML Canvas API, and the blend func is based on OpenGL (see corresponding manuals for more info). The colors in the blending state have premultiplied alpha. Sets the composite operation. The op parameter should be one of NVGcompositeOperation.","args": ["op"]},{"name": "nvgGlobalCompositeBlendFunc","js": "globalCompositeBlendFunc","section": "Composite operation","signature": "void nvgGlobalCompositeBlendFunc(NVGcontext* ctx, int sfactor, int dfactor)","doc": "Sets the composite operation with custom pixel arithmetic. The parameters should be one of NVGblendFactor.","args": ["sfactor","dfactor"]},{"name": "nvgGlobalCompositeBlendFuncSeparate","js": "globalCompositeBlendFuncSeparate","section": "Composite operation","signature": "void nvgGlobalCompositeBlendFuncSeparate(NVGcontext* ctx, int srcRGB, int dstRGB, int srcAlpha, int dstAlpha)","doc": "Sets the composite operation with custom pixel arithmetic for RGB and alpha components separately. The parameters should be one of NVGblendFactor.","args": ["srcRGB","dstRGB","srcAlpha","dstAlpha"]},{"name": "nvgRGB","js": "rgb","section": "Color utils","signature": "NVGcolor nvgRGB(unsigned char r, unsigned char g, unsigned char b)","doc": "Colors in NanoVG are stored as unsigned ints in ABGR format. Returns a color value from red, green, blue values. Alpha will be set to 255 (1.0f).","args": ["r","g","b"]},{"name": "nvgRGBf","js": "rgbf","section": "Color utils","signature": "NVGcolor nvgRGBf(float r, float g, float b)","doc": "Returns a color value from red, green, blue values. Alpha will be set to 1.0f.","args": ["r","g","b"]},{"name": "nvgRGBA","js": "rgba","section": "Color utils","signature": "NVGcolor nvgRGBA(unsigned char r, unsigned char g, unsigned char b, unsigned char a)","doc": "Returns a color value from red, green, blue and alpha values.","args": ["r","g","b","a"]},{"name": "nvgRGBAf","js": "rgbaf","section": "Color utils","signature": "NVGcolor nvgRGBAf(float r, float g, float b, float a)","doc": "Returns a color value from red, green, blue and alpha values.","args": ["r","g","b","a"]},{"name": "nvgLerpRGBA","js": "lerpRGBA","section": "Color utils","signature": "NVGcolor nvgLerpRGBA(NVGcolor c0, NVGcolor c1, float u)","doc": "Linearly interpolates from color c0 to c1, and returns resulting color value.","args": ["c0","c1","u"]},{"name": "nvgTransRGBA","js": "transRGBA","section": "Color utils","signature": "NVGcolor nvgTransRGBA(NVGcolor c0, unsigned char a)","doc": "Sets transparency of a color value.","args": ["c0","a"]},{"name": "nvgTransRGBAf","js": "transRGBAf","section": "Color utils","signature": "NVGcolor nvgTransRGBAf(NVGcolor c0, float a)","doc": "Sets transparency of a color value.","args": ["c0","a"]},{"name": "nvgHSL","js": "hsl","section": "Color utils","signature": "NVGcolor nvgHSL(float h, float s, float l)","doc": "Returns color value specified by hue, saturation and lightness. HSL values are all in range [0..1], alpha will be set to 255.","args": ["h","s","l"]},{"name": "nvgHSLA","js": "hsla","section": "Color utils","signature": "NVGcolor nvgHSLA(float h, float s, float l, unsigned char a)","doc": "Returns color value specified by hue, saturation and lightness and alpha. HSL values are all in range [0..1], alpha in range [0..255]","args": ["h","s","l","a"]},{"name": "nvgSave","js": "save","section": "State Handling","signature": "void nvgSave(NVGcontext* ctx)","doc": "NanoVG contains state which represents how paths will be rendered. The state contains transform, fill and stroke styles, text and font styles, and scissor clipping. Pushes and saves the current render state into a state stack. A matching nvgRestore() must be used to restore the state.","args": []},{"name": "nvgRestore","js": "restore","section": "State Handling","signature": "void nvgRestore(NVGcontext* ctx)","doc": "Pops and restores current render state.","args": []},{"name": "nvgReset","js": "reset","section": "State Handling","signature": "void nvgReset(NVGcontext* ctx)","doc": "Resets current render state to default values. Does not affect the render state stack.","args": []},{"name": "nvgShapeAntiAlias","js": "shapeAntiAlias","section": "Render styles","signature": "void nvgShapeAntiAlias(NVGcontext* ctx, int enabled)","doc": "Fill and stroke render style can be either a solid color or a paint which is a gradient or a pattern. Solid color is simply defined as a color value, different kinds of paints can be created using nvgLinearGradient(), nvgBoxGradient(), nvgRadialGradient() and nvgImagePattern(). Current render style can be saved and restored using nvgSave() and nvgRestore(). Sets whether to draw antialias for nvgStroke() and nvgFill(). It's enabled by default.","args": ["enabled"]},{"name": "nvgStrokeColor","js": "strokeColor","section": "Render styles","signature": "void nvgStrokeColor(NVGcontext* ctx, NVGcolor color)","doc": "Sets current stroke style to a solid color.","args": ["color"]},{"name": "nvgStrokePaint","js": "strokePaint","section": "Render styles","signature": "void nvgStrokePaint(NVGcontext* ctx, NVGpaint paint)","doc": "Sets current stroke style to a paint, which can be a one of the gradients or a pattern.","args": ["paint"]},{"name": "nvgFillColor","js": "fillColor","section": "Render styles","signature": "void nvgFillColor(NVGcontext* ctx, NVGcolor color)","doc": "Sets current fill style to a solid color.","args": ["color"]},{"name": "nvgFillPaint","js": "fillPaint","section": "Render styles","signature": "void nvgFillPaint(NVGcontext* ctx, NVGpaint paint)","doc": "Sets current fill style to a paint, which can be a one of the gradients or a pattern.","args": ["paint"]},{"name": "nvgMiterLimit","js": "miterLimit","section": "Render styles","signature": "void nvgMiterLimit(NVGcontext* ctx, float limit)","doc": "Sets the miter limit of the stroke style. Miter limit controls when a sharp corner is beveled.","args": ["limit"]},{"name": "nvgStrokeWidth","js": "strokeWidth","section": "Render styles","signature": "void nvgStrokeWidth(NVGcontext* ctx, float width)","doc": "Sets the stroke width of the stroke style.","args": ["width"]},{"name": "nvgLineStyle","js": "lineStyle","section": "Render styles","signature": "void nvgLineStyle(NVGcontext* ctx, int lineStyle)","doc": "Sets how line is drawn. Can be one of NVG_LINE_SOLID (default), NVG_LINE_GLOW, NVG_LINE_DASHED, NVG_LINE_DOTTED","args": ["lineStyle"]},{"name": "nvgLineCap","js": "lineCap","section": "Render styles","signature": "void nvgLineCap(NVGcontext* ctx, int cap)","doc": "Sets how the end of the line (cap) is drawn, Can be one of: NVG_BUTT (default), NVG_ROUND, NVG_SQUARE.","args": ["cap"]},{"name": "nvgLineJoin","js": "lineJoin","section": "Render styles","signature": "void nvgLineJoin(NVGcontext* ctx, int join)","doc": "Sets how sharp path corners are drawn. Can be one of NVG_MITER (default), NVG_ROUND, NVG_BEVEL.","args": ["join"]},{"name": "nvgGlobalAlpha","js": "globalAlpha","section": "Render styles","signature": "void nvgGlobalAlpha(NVGcontext* ctx, float alpha)","doc": "Sets the transparency applied to all rendered shapes. Already transparent paths will get proportionally more transparent as well.","args": ["alpha"]},{"name": "nvgResetTransform","js": "resetTransform","section": "Transforms","signature": "void nvgResetTransform(NVGcontext* ctx)","doc": "The paths, gradients, patterns and scissor region are transformed by an transformation matrix at the time when they are passed to the API. The current transformation matrix is a affine matrix: [sx kx tx] [ky sy ty] [ 0  0  1] Where: sx,sy define scaling, kx,ky skewing, and tx,ty translation. The last row is assumed to be 0,0,1 and is not stored. Apart from nvgResetTransform(), each transformation function first creates specific transformation matrix and pre-multiplies the current transformation by it. Current coordinate system (transformation) can be saved and restored using nvgSave() and nvgRestore(). Resets current transform to a identity matrix.","args": []},{"name": "nvgTransform","js": "transform","section": "Transforms","signature": "void nvgTransform(NVGcontext* ctx, float a, float b, float c, float d, float e, float f)","doc": "Premultiplies current coordinate system by specified matrix. The parameters are interpreted as matrix as follows: [a c e] [b d f] [0 0 1]","args": ["a","b","c","d","e","f"]},{"name": "nvgTranslate","js": "translate","section": "Transforms","signature": "void nvgTranslate(NVGcontext* ctx, float x, float y)","doc": "Translates current coordinate system.","args": ["x","y"]},{"name": "nvgRotate","js": "rotate","section": "Transforms","signature": "void nvgRotate(NVGcontext* ctx, float angle)","doc": "Rotates current coordinate system. Angle is specified in radians.","args": ["angle"]},{"name": "nvgSkewX","js": "skewX","section": "Transforms","signature": "void nvgSkewX(NVGcontext* ctx, float angle)","doc": "Skews the current coordinate system along X axis. Angle is specified in radians.","args": ["angle"]},{"name": "nvgSkewY","js": "skewY","section": "Transforms","signature": "void nvgSkewY(NVGcontext* ctx, float angle)","doc": "Skews the current coordinate system along Y axis. Angle is specified in radians.","args": ["angle"]},{"name": "nvgScale","js": "scale","section": "Transforms","signature": "void nvgScale(NVGcontext* ctx, float x, float y)","doc": "Scales the current coordinate system.","args": ["x","y"]},{"name": "nvgDegToRad","js": "degToRad","section": "Transforms","signature": "float nvgDegToRad(float deg)","doc": "Converts degrees to radians and vice versa.","args": ["deg"]},{"name": "nvgRadToDeg","js": "radToDeg","section": "Transforms","signature": "float nvgRadToDeg(float rad)","doc": "","args": ["rad"]},{"name": "nvgDeleteImage","js": "deleteImage","section": "Images","signature": "void nvgDeleteImage(NVGcontext* ctx, int image)","doc": "Deletes created image.","args": ["image"]},{"name": "nvgLinearGradient","js": "linearGradient","section": "Paints","signature": "NVGpaint nvgLinearGradient(NVGcontext* ctx, float sx, float sy, float ex, float ey, NVGcolor icol, NVGcolor ocol)","doc": "NanoVG supports four types of paints: linear gradient, box gradient, radial gradient and image pattern. These can be used as paints for strokes and fills. Creates and returns a linear gradient. Parameters (sx,sy)-(ex,ey) specify the start and end coordinates of the linear gradient, icol specifies the start color and ocol the end color. The gradient is transformed by the current transform when it is passed to nvgFillPaint() or nvgStrokePaint().","args": ["sx","sy","ex","ey","icol","ocol"]},{"name": "nvgBoxGradient","js": "boxGradient","section": "Paints","signature": "NVGpaint nvgBoxGradient(NVGcontext* ctx, float x, float y, float w, float h, float r, float f, NVGcolor icol, NVGcolor ocol)","doc": "Creates and returns a box gradient. Box gradient is a feathered rounded rectangle, it is useful for rendering drop shadows or highlights for boxes. Parameters (x,y) define the top-left corner of the rectangle, (w,h) define the size of the rectangle, r defines the corner radius, and f feather. Feather defines how blurry the border of the rectangle is. Parameter icol specifies the inner color and ocol the outer color of the gradient. The gradient is transformed by the current transform when it is passed to nvgFillPaint() or nvgStrokePaint().","args": ["x","y","w","h","r","f","icol","ocol"]},{"name": "nvgRadialGradient","js": "radialGradient","section": "Paints","signature": "NVGpaint nvgRadialGradient(NVGcontext* ctx, float cx, float cy, float inr, float outr, NVGcolor icol, NVGcolor ocol)","doc": "Creates and returns a radial gradient. Parameters (cx,cy) specify the center, inr and outr specify the inner and outer radius of the gradient, icol specifies the start color and ocol the end color. The gradient is transformed by the current transform when it is passed to nvgFillPaint() or nvgStrokePaint().","args": ["cx","cy","inr","outr","icol","ocol"]},{"name": "nvgImagePattern","js": "imagePattern","section": "Paints","signature": "NVGpaint nvgImagePattern(NVGcontext* ctx, float ox, float oy, float ex, float ey, float angle, int image, float alpha)","doc": "Creates and returns an image pattern. Parameters (ox,oy) specify the left-top location of the image pattern, (ex,ey) the size of one image, angle rotation around the top-left corner, image is handle to the image to render. The gradient is transformed by the current transform when it is passed to nvgFillPaint() or nvgStrokePaint().","args": ["ox","oy","ex","ey","angle","image","alpha"]},{"name": "nvgScissor","js": "scissor","section": "Scissoring","signature": "void nvgScissor(NVGcontext* ctx, float x, float y, float w, float h)","doc": "Scissoring allows you to clip the rendering into a rectangle. This is useful for various user interface cases like rendering a text edit or a timeline. Sets the current scissor rectangle. The scissor rectangle is transformed by the current transform.","args": ["x","y","w","h"]},{"name": "nvgIntersectScissor","js": "intersectScissor","section": "Scissoring","signature": "void nvgIntersectScissor(NVGcontext* ctx, float x, float y, float w, float h)","doc": "Intersects current scissor rectangle with the specified rectangle. The scissor rectangle is transformed by the current transform. Note: in case the rotation of previous scissor rect differs from the current one, the intersection will be done between the specified rectangle and the previous scissor rectangle transformed in the current transform space. The resulting shape is always rectangle.","args": ["x","y","w","h"]},{"name": "nvgResetScissor","js": "resetScissor","section": "Scissoring","signature": "void nvgResetScissor(NVGcontext* ctx)","doc": "Reset and disables scissoring.","args": []},{"name": "nvgBeginPath","js": "beginPath","section": "Paths","signature": "void nvgBeginPath(NVGcontext* ctx)","doc": "Drawing a new shape starts with nvgBeginPath(), it clears all the currently defined paths. Then you define one or more paths and sub-paths which describe the shape. The are functions to draw common shapes like rectangles and circles, and lower level step-by-step functions, which allow to define a path curve by curve. NanoVG uses even-odd fill rule to draw the shapes. Solid shapes should have counter clockwise winding and holes should have counter clockwise order. To specify winding of a path you can call nvgPathWinding(). This is useful especially for the common shapes, which are drawn CCW. Finally you can fill the path using current fill style by calling nvgFill(), and stroke it with current stroke style by calling nvgStroke(). The curve segments and sub-paths are transformed by the current transform. Clears the current path and sub-paths.","args": []},{"name": "nvgMoveTo","js": "moveTo","section": "Paths","signature": "void nvgMoveTo(NVGcontext* ctx, float x, float y)","doc": "Starts new sub-path with specified point as first point.","args": ["x","y"]},{"name": "nvgLineTo","js": "lineTo","section": "Paths","signature": "void nvgLineTo(NVGcontext* ctx, float x, float y)","doc": "Adds line segment from the last point in the path to the specified point.","args": ["x","y"]},{"name": "nvgBezierTo","js": "bezierTo","section": "Paths","signature": "void nvgBezierTo(NVGcontext* ctx, float c1x, float c1y, float c2x, float c2y, float x, float y)","doc": "Adds cubic bezier segment from last point in the path via two control points to the specified point.","args": ["c1x","c1y","c2x","c2y","x","y"]},{"name": "nvgQuadTo","js": "quadTo","section": "Paths","signature": "void nvgQuadTo(NVGcontext* ctx, float cx, float cy, float x, float y)","doc": "Adds quadratic bezier segment from last point in the path via a control point to the specified point.","args": ["cx","cy","x","y"]},{"name": "nvgArcTo","js": "arcTo","section": "Paths","signature": "void nvgArcTo(NVGcontext* ctx, float x1, float y1, float x2, float y2, float radius)","doc": "Adds an arc segment at the corner defined by the last path point, and two specified points.","args": ["x1","y1","x2","y2","radius"]},{"name": "nvgClosePath","js": "closePath","section": "Paths","signature": "void nvgClosePath(NVGcontext* ctx)","doc": "Closes current sub-path with a line segment.","args": []},{"name": "nvgPathWinding","js": "pathWinding","section": "Paths","signature": "void nvgPathWinding(NVGcontext* ctx, int dir)","doc": "Sets the current sub-path winding, see NVGwinding and NVGsolidity.","args": ["dir"]},{"name": "nvgArc","js": "arc","section": "Paths","signature": "void nvgArc(NVGcontext* ctx, float cx, float cy, float r, float a0, float a1, int dir)","doc": "Creates new circle arc shaped sub-path. The arc center is at cx,cy, the arc radius is r, and the arc is drawn from angle a0 to a1, and swept in direction dir (NVG_CCW, or NVG_CW). Angles are specified in radians.","args": ["cx","cy","r","a0","a1","dir"]},{"name": "nvgRect","js": "rect","section": "Paths","signature": "void nvgRect(NVGcontext* ctx, float x, float y, float w, float h)","doc": "Creates new rectangle shaped sub-path.","args": ["x","y","w","h"]},{"name": "nvgRoundedRect","js": "roundedRect","section": "Paths","signature": "void nvgRoundedRect(NVGcontext* ctx, float x, float y, float w, float h, float r)","doc": "Creates new rounded rectangle shaped sub-path.","args": ["x","y","w","h","r"]},{"name": "nvgRoundedRectVarying","js": "roundedRectVarying","section": "Paths","signature": "void nvgRoundedRectVarying(NVGcontext* ctx, float x, float y, float w, float h, float radTopLeft, float radTopRight, float radBottomRight, float radBottomLeft)","doc": "Creates new rounded rectangle shaped sub-path with varying radii for each corner.","args": ["x","y","w","h","radTopLeft","radTopRight","radBottomRight","radBottomLeft"]},{"name": "nvgEllipse","js": "ellipse","section": "Paths","signature": "void nvgEllipse(NVGcontext* ctx, float cx, float cy, float rx, float ry)","doc": "Creates new ellipse shaped sub-path.","args": ["cx","cy","rx","ry"]},{"name": "nvgCircle","js": "circle","section": "Paths","signature": "void nvgCircle(NVGcontext* ctx, float cx, float cy, float r)","doc": "Creates new circle shaped sub-path.","args": ["cx","cy","r"]},{"name": "nvgFill","js": "fill","section": "Paths","signature": "void nvgFill(NVGcontext* ctx)","doc": "Fills the current path with current fill style.","args": []},{"name": "nvgStroke","js": "stroke","section": "Paths","signature": "void nvgStroke(NVGcontext* ctx)","doc": "Fills the current path with current stroke style.","args": []},{"name": "nvgFindFont","js": "findFont","section": "At render time the font face can be set based on the font handles or name.","signature": "int nvgFindFont(NVGcontext* ctx, const char* name)","doc": "Finds a loaded font of specified name, and returns handle to it, or -1 if the font is not found.","args": ["name"]},{"name": "nvgAddFallbackFontId","js": "addFallbackFontId","section": "At render time the font face can be set based on the font handles or name.","signature": "int nvgAddFallbackFontId(NVGcontext* ctx, int baseFont, int fallbackFont)","doc": "Adds a fallback font by handle.","args": ["baseFont","fallbackFont"]},{"name": "nvgAddFallbackFont","js": "addFallbackFont","section": "At render time the font face can be set based on the font handles or name.","signature": "int nvgAddFallbackFont(NVGcontext* ctx, const char* baseFont, const char* fallbackFont)","doc": "Adds a fallback font by name.","args": ["baseFont","fallbackFont"]},{"name": "nvgResetFallbackFontsId","js": "resetFallbackFontsId","section": "At render time the font face can be set based on the font handles or name.","signature": "void nvgResetFallbackFontsId(NVGcontext* ctx, int baseFont)","doc": "Resets fallback fonts by handle.","args": ["baseFont"]},{"name": "nvgResetFallbackFonts","js": "resetFallbackFonts","section": "At render time the font face can be set based on the font handles or name.","signature": "void nvgResetFallbackFonts(NVGcontext* ctx, const char* baseFont)","doc": "Resets fallback fonts by name.","args": ["baseFont"]},{"name": "nvgFontSize","js": "fontSize","section": "At render time the font face can be set based on the font handles or name.","signature": "void nvgFontSize(NVGcontext* ctx, float size)","doc": "Sets the font size of current text style.","args": ["size"]},{"name": "nvgFontBlur","js": "fontBlur","section": "At render time the font face can be set based on the font handles or name.","signature": "void nvgFontBlur(NVGcontext* ctx, float blur)","doc": "Sets the blur of current text style.","args": ["blur"]},{"name": "nvgFontDilate","js": "fontDilate","section": "At render time the font face can be set based on the font handles or name.","signature": "void nvgFontDilate(NVGcontext* ctx, float dilate)","doc": "Sets the dilation of current text style.","args": ["dilate"]},{"name": "nvgTextLetterSpacing","js": "textLetterSpacing","section": "At render time the font face can be set based on the font handles or name.","signature": "void nvgTextLetterSpacing(NVGcontext* ctx, float spacing)","doc": "Sets the letter spacing of current text style.","args": ["spacing"]},{"name": "nvgTextLineHeight","js": "textLineHeight","section": "At render time the font face can be set based on the font handles or name.","signature": "void nvgTextLineHeight(NVGcontext* ctx, float lineHeight)","doc": "Sets the proportional line height of current text style. The line height is specified as multiple of font size.","args": ["lineHeight"]},{"name": "nvgTextAlign","js": "textAlign","section": "At render time the font face can be set based on the font handles or name.","signature": "void nvgTextAlign(NVGcontext* ctx, int align)","doc": "Sets the text align of current text style, see NVGalign for options.","args": ["align"]},{"name": "nvgFontFaceId","js": "fontFaceId","section": "At render time the font face can be set based on the font handles or name.","signature": "void nvgFontFaceId(NVGcontext* ctx, int font)","doc": "Sets the font face based on specified id of current text style.","args": ["font"]},{"name": "nvgFontFace","js": "fontFace","section": "At render time the font face can be set based on the font handles or name.","signature": "void nvgFontFace(NVGcontext* ctx, const char* font)","doc": "Sets the font face based on specified name of current text style.","args": ["font"]},{"name": "nvgText","js": "text","section": "At render time the font face can be set based on the font handles or name.","signature": "float nvgText(NVGcontext* ctx, float x, float y, const char* string, const char* end)","doc": "Draws text string at specified location. If end is specified only the sub-string up to the end is drawn.","args": ["x","y","string"]},{"name": "nvgTextBox","js": "textBox","section": "At render time the font face can be set based on the font handles or name.","signature": "void nvgTextBox(NVGcontext* ctx, float x, float y, float breakRowWidth, const char* string, const char* end)","doc": "Draws multi-line text string at specified location wrapped at the specified width. If end is specified only the sub-string up to the end is drawn. The text is split at word boundaries or when new-line characters are encountered. Words longer than the max width are slit at nearest character (i.e. no hyphenation).","args": ["x","y","breakRowWidth","string"]},{"name": "nvgFontQuality","js": "fontQuality","section": "At render time the font face can be set based on the font handles or name.","signature": "void nvgFontQuality(NVGcontext* ctx, float quality)","doc": "","args": ["quality"]},{"name": "nvgStencil","js": "stencil","section": "At render time the font face can be set based on the font handles or name.","signature": "void nvgStencil(NVGcontext* ctx)","doc": "Work like nvgFill, but only supports drawing image with alpha channels. The image is used to create a stencil buffer, which will be used for subsequent drawing operations, and only the content corresponding to the non-transparent part of the stencil buffer will be displayed.","args": []},{"name": "nvgStencilClear","js": "stencilClear","section": "At render time the font face can be set based on the font handles or name.","signature": "void nvgStencilClear(NVGcontext* ctx)","doc": "Clear stencil buffer and disable stencil test.","args": []}];
